<section class="card card-body mb-4" aria-labelledby="working-property-title"><h2 class="h5" id="working-property-title">Inmueble para visitas y reservas</h2><p class="small text-muted">Actual: <strong><?= e($lead['titulo'] ?? 'Sin inmueble seleccionado') ?></strong>. Las oportunidades pueden representar alternativas; selecciona aquí la que deseas trabajar.</p>
<?php if ($commercialOpen): ?><form method="post" action="<?= BASE_URL ?>/crm/property?id=<?= (int)$lead['id'] ?>"><?= Csrf::field() ?><div class="row g-3"><div class="col-md-9"><label class="form-label" for="working_property_id">Inmueble de trabajo</label><select class="form-select" id="working_property_id" name="propiedad_id" required><option value="">Selecciona un inmueble</option><?php foreach ($propertyOptions as $option): ?><option value="<?= (int)$option['id'] ?>" <?= (int)$lead['propiedad_id']===(int)$option['id'] ? 'selected' : '' ?>><?= e($option['titulo']) ?> · <?= e($option['moneda']) ?> <?= number_format((float)$option['precio'],0) ?> · <?= e(ucfirst($option['disponibilidad'])) ?></option><?php endforeach; ?></select></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary" type="submit">Guardar inmueble</button></div></div><p class="form-text mb-0">Para cambiarlo, resuelve las visitas activas y cancela las reservas pendientes o aprobadas. El historial conserva los inmuebles originales.</p></form><?php else: ?><p class="small text-muted mb-0">La consulta está finalizada. Su inmueble y su historial se conservan.</p><?php endif; ?></section>
<?php require __DIR__.'/../opportunities/crm.php'; ?>
<section class="card card-body mb-4"><div class="d-flex justify-content-between align-items-center gap-3"><h2 class="h5 mb-0">Reservas de la consulta</h2><?php if ($canReserve): ?><a class="btn btn-outline-primary" href="<?= BASE_URL ?>/reservations/create?lead_id=<?= (int)$lead['id'] ?>">Solicitar reserva</a><?php endif; ?></div><?php if (!$reservations): ?><p class="text-muted mt-3 mb-0">Aún no hay reservas para esta consulta.</p><?php endif; ?><?php foreach ($reservations as $reservation): ?><div class="border-top mt-3 pt-3">#<?= (int)$reservation['id'] ?> · <?= e($reservation['titulo']) ?> · <?= e(Reservation::STATES[$reservation['estado_reserva']]) ?> · <?= e($reservation['moneda']) ?> <?= number_format((float)$reservation['monto_reserva'],0) ?><?php if ($user['rol']!=='vendedor' || (int)$reservation['vendedor_id']===$user['id']): ?> · <a href="<?= BASE_URL ?>/reservations/show?id=<?= (int)$reservation['id'] ?>">Gestionar</a><?php endif; ?></div><?php endforeach; ?></section>
<section class="card card-body mb-4"><div class="d-flex justify-content-between gap-3 align-items-center"><h2 class="h5 mb-0">Visitas de la consulta</h2><?php if ($canSchedule): ?><a class="btn btn-outline-primary" href="<?= BASE_URL ?>/visits/create?lead_id=<?= (int)$lead['id'] ?>">Programar visita</a><?php endif; ?></div><?php if (!$visits): ?><p class="text-muted mt-3 mb-0">Aún no hay visitas programadas.</p><?php endif; ?><?php foreach ($visits as $visit): ?><div class="border-top mt-3 pt-3"><?= e($visit['titulo']) ?> · <?= e($visit['fecha_hora']) ?> (Lima) · <?= e(Visit::MODES[$visit['modalidad']]) ?> · <?= e(Visit::STATES[$visit['estado_visita']]) ?><?php if ($user['rol']!=='vendedor' || (int)$visit['vendedor_id']===$user['id']): ?> · <a href="<?= BASE_URL ?>/visits/edit?id=<?= (int)$visit['id'] ?>">Gestionar</a><?php endif; ?></div><?php endforeach; ?></section>


<div class="row g-4"><div class="col-lg-4"><section class="card card-body"><h2 class="h5">Datos del contacto</h2><p><?= e($lead['nombres'].' '.($lead['apellidos'] ?? '')) ?></p><p>Correo: <?= e($lead['email'] ?? 'No indicado') ?><br>Teléfono: <?= e($lead['telefono'] ?? 'No indicado') ?></p><hr><h2 class="h5">Inmueble de trabajo</h2><p><?= e($lead['titulo'] ?? 'Sin inmueble') ?></p><p class="small text-muted">Origen: <?= e($lead['origen']) ?> · <?= e($lead['created_at']) ?></p><h2 class="h6">Mensaje recibido</h2><p class="mb-0" style="white-space:pre-wrap"><?= e($lead['notas']) ?></p></section></div>
