<?php if ($user['rol']!=='vendedor'): ?><div class="col-md-6"><label class="form-label" for="vendedor_id">Asignar vendedor</label><select class="form-select" name="vendedor_id" id="vendedor_id"><option value="">Sin asignar</option><?php foreach ($sellers as $seller): ?><option value="<?= (int)$seller['id'] ?>" <?= (string)($old['vendedor_id'] ?? $lead['vendedor_id'])===(string)$seller['id'] ? 'selected' : '' ?>><?= e($seller['nombre']) ?></option><?php endforeach; ?></select><?php if (!$sellers): ?><div class="form-text">No hay usuarios activos con rol vendedor.</div><?php endif; ?></div><?php endif; ?>
<div class="col-md-6"><label class="form-label" for="tipo">Tipo de seguimiento</label><select class="form-select" id="tipo" name="tipo"><?php foreach (Lead::TYPES as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($old['tipo'] ?? 'nota')===$value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label" for="proxima_accion">Próxima acción (hora de Lima)</label><input class="form-control" type="datetime-local" id="proxima_accion" name="proxima_accion" value="<?= e($old['proxima_accion'] ?? '') ?>"><div class="form-text">Aparecerá en el Centro de pendientes. No envía avisos externos.</div></div><div class="col-12"><label class="form-label" for="detalle">Agregar seguimiento</label><textarea class="form-control" id="detalle" name="detalle" rows="4" maxlength="4000" placeholder="Ej. Se llamó al cliente y solicitó una visita."><?= e($old['detalle'] ?? '') ?></textarea></div><div class="col-12"><button class="btn btn-primary">Guardar cambios</button></div></div></form>
<section class="card card-body"><h2 class="h5">Historial de seguimiento</h2><?php if (!$history): ?><p class="text-muted mb-0">Aún no hay seguimientos.</p><?php endif; ?><?php foreach ($history as $entry): ?><article class="border-top pt-3 mt-3"><div class="d-flex justify-content-between gap-2"><strong><?= e(Lead::TYPES[$entry['tipo']]) ?> · <?= e($entry['autor']) ?></strong><span class="small text-muted"><?= e($entry['created_at']) ?></span></div><p class="mt-2 mb-1" style="white-space:pre-wrap"><?= e($entry['detalle']) ?></p><?php if ($entry['proxima_accion']): ?><p class="small text-primary">Próxima acción: <?= e($entry['proxima_accion']) ?> (Lima)</p><?php require __DIR__.'/../tasks/crm-action.php'; ?><?php endif; ?></article><?php endforeach; ?></section></div></div>
<?php if ($conversation): ?><section class="card card-body mt-4"><h2 class="h5">Conversación del asistente</h2><p class="small text-muted">Contexto compartido por el visitante al enviar su consulta. Los precios y la disponibilidad pueden haber cambiado.</p><?php foreach ($conversation as $entry): $meta=json_decode($entry['metadatos'] ?? '',true) ?: []; ?><article class="border-top py-3"><p class="small text-muted"><?= $entry['emisor']==='cliente' ? 'Visitante' : (($meta['source'] ?? '')==='openai' ? 'Asistente IA' : 'Sistema / búsqueda guiada') ?> · <?= e($entry['created_at']) ?></p><p class="mb-0" style="white-space:pre-wrap;overflow-wrap:anywhere"><?= e($entry['contenido']) ?></p></article><?php endforeach; ?></section><?php endif; ?>

